for row in grid:
    for cell in row:
        # If the cell has not been visited before, mark it as visited
        if cell not in visited:
            visited[cell] = 1

        # If the current cell is the starting point, mark it as the first cell of the path
        if cell == 0:
            path_len = 1

        # Otherwise, mark the current cell as the next cell in the path
        else:
            path_len += 1

        # If the path length is less than or equal to k, return the path
        if path_len <= k:
            return [cell]

        # Otherwise, move to the next cell and repeat the process
        else:
            visited[cell] = 0

