def StrongestExtension(class_name, extensions):
   strength = 0
   strongest_extension = None
   for extension in extensions:
       cap = len(re.findall(r'[A-Z]', extension))
       sm = len(re.findall(r'[a-z]', extension))
       strength += cap - sm
       if not strongest_extension or strength > strongest_extension[2]:
           strongest_extension = (extension, cap - sm)
   return class_name + '.' + strongest_extension[0]

def StrongestExtension(class_name, extensions):
   strongest_extension = extensions[0]
   for extension in extensions[1:]:
       current_strength = len(extension.title()) - len(extension.lower())
       if current_strength > strongest_extension:
           strongest_extension = extension
   return f"{class_name}.{strongest_extension}"

